#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import csv
import datetime as dt
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

KG = {"kg": Decimal(1), "g": Decimal("0.001"), "lb": Decimal("0.45392"), "oz": Decimal("0.02837")}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
HARBOR_STATUS = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                 "ret": "returned", "hld": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}
MONTHS = {m: i + 1 for i, m in enumerate("jan feb mar apr may jun jul aug sep oct nov dec".split())}

COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
DELIM = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
FIELD = {  # logical name -> column name per depot
    "east": dict(id="id", type="type", date="shipped", weight="gross", status="status"),
    "lakeside": dict(id="id", type="kind", date="shipped", weight="gross_kg", status="status"),
    "harbor": dict(id="ref", type="rec", date="date", weight="weight", status="state"),
    "river": dict(id="ref", type="t", date="shipped", weight="weight", status="status"),
    "west": dict(id="id", type="typ", date="shipped", weight="typ" and "weight", status="status"),
}
BASE_DATE = {"east": "ymd", "lakeside": "iso", "harbor": "iso", "river": "mm/dd/yyyy",
             "west": "dd.mm.yyyy"}
DECIMAL_COMMA = {"west"}


class Rec:
    __slots__ = ("num", "kind", "month", "kg", "status")

    def __init__(self, num, kind, month=None, kg=None, status=None):
        self.num, self.kind, self.month, self.kg, self.status = num, kind, month, kg, status


def warn(*a):
    print(*a, file=sys.stderr)


# ---------- bytes and text ----------
def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b[2:].decode("utf-16-le" if b[:2] == b"\xff\xfe" else "utf-16-be")
    head = b[:4096].decode("latin-1")
    for line in head.split("\n")[:30]:
        m = re.match(r"#\s*charset\s*:\s*([\w.\-]+)", line)
        if m:
            try:
                return b.decode(m.group(1).strip())
            except (LookupError, UnicodeDecodeError):
                break
    return b.decode("utf-8", "replace")


def lines_of(text):
    return [l[:-1] if l.endswith("\r") else l for l in text.split("\n")]


# ---------- values ----------
def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def id_num(s):
    m = re.match(r"\s*SH\D*(\d+)\s*$", s or "", re.I)
    return int(m.group(1)) if m else None


def norm_kind(s):
    s = (s or "").strip().lower()
    if s[:1] in ("c", "a"):
        return "correction"
    if s[:1] == "v":
        return "void"
    return "new"


def parse_unit(s):
    m = re.match(r"\s*(kg|g|lb|oz)\b", (s or "").strip().lower())
    return m.group(1) if m else None


def parse_number(s, comma_decimal):
    s = s.strip().replace(" ", "")
    if comma_decimal:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Decimal(s)


def weight_kg(text, unit_hint, comma_decimal):
    """text may carry its own unit suffix; unit_hint is the fallback."""
    m = re.match(r"^\s*([-+0-9.,\s]+?)\s*(kg|g|lb|oz)?\s*$", str(text), re.I)
    if not m:
        raise ValueError("bad weight %r" % (text,))
    unit = (m.group(2) or unit_hint or "kg").lower()
    return parse_number(m.group(1), comma_decimal) * KG[unit]


def parse_date(s, form):
    s = (s or "").strip()
    if not s:
        raise ValueError("empty date")
    if "T" in s or re.match(r"\d{4}-\d\d-\d\d[ T]\d", s):
        return iso_time(s).date()
    f = (form or "iso").strip().lower()
    if f == "serial":
        return dt.date(1899, 12, 31) + dt.timedelta(days=int(float(s)) - 1)
    m = re.match(r"(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$", s)
    if m:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    p = [int(x) for x in re.split(r"\D+", s) if x]
    if f in ("iso", "ymd", "yyyy-mm-dd"):
        y, mo, d = p[:3]
    elif f in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy", "dd-mm-yyyy"):
        d, mo, y = p[:3]
    elif f in ("mm/dd/yyyy", "mdy"):
        mo, d, y = p[:3]
    elif f == "yyyyddd":
        return dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:7]) - 1)
    elif f == "yyyymmdd":
        return dt.date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    else:
        raise ValueError("unknown date form %r" % f)
    return dt.date(y, mo, d)


def iso_time(s):
    s = s.strip().replace(" ", "T", 1)
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    t = dt.datetime.fromisoformat(s)
    if t.tzinfo is None:
        return t
    return t.astimezone(dt.timezone.utc)


def month_of_time(s):
    t = iso_time(s)
    return "%04d-%02d" % (t.year, t.month)


def month_of_date(d):
    return "%04d-%02d" % (d.year, d.month)


# ---------- delimited text ----------
def split_records(lines):
    """Yield ('comment', line) or ('row', text) honoring quoted multi-line fields."""
    buf = None
    for l in lines:
        if buf is None:
            if l.startswith("#"):
                yield "comment", l
                continue
            if not l.strip():
                continue
            buf = l
        else:
            buf += "\n" + l
        if buf.count('"') % 2 == 0:
            yield "row", buf
            buf = None
    if buf is not None:
        yield "row", buf


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLUMNS[depot]
    fmap = FIELD[depot]
    seq = None
    date_form = BASE_DATE[depot]
    unit = None
    comma_dec = depot in DECIMAL_COMMA
    hdr = None
    recs = []
    for kind, item in split_records(lines_of(text)):
        if kind == "comment":
            m = re.match(r"#\s*([^:=]+?)\s*:\s*(.*?)\s*$", item)
            if m:
                name, val = m.group(1).strip().lower(), m.group(2)
                if name == "seq":
                    seq = int(val)
                elif "date" in name:
                    date_form = val.strip().split()[0] if val.strip() else date_form
                elif "unit" in name:
                    u = parse_unit(val)
                    if u:
                        unit = u
                    if "decimal comma" in val.lower():
                        comma_dec = True
                    elif "decimal point" in val.lower() or "decimal dot" in val.lower():
                        comma_dec = False
            else:
                m = re.search(r"\bseq\s*=\s*(\d+)", item)
                if m:
                    seq = int(m.group(1))
            continue
        if delim == ",":
            row = next(csv.reader(io.StringIO(item, newline=""), delimiter=",", quotechar='"'))
        else:
            row = item.split(delim)
        low = [c.strip().lower() for c in row]
        if all(c in cols for c in low):
            hdr = low
            continue
        if hdr is None:
            continue
        widx = hdr.index(fmap["weight"]) if fmap["weight"] in hdr else None
        row_unit = None
        if len(row) == len(hdr) + 1 and widx is not None:
            row_unit = parse_unit(row[widx + 1])
            if row_unit is None:
                warn("unexpected extra field", row)
            row = row[:widx + 1] + row[widx + 2:]
        if len(row) < len(hdr):
            row = row + [""] * (len(hdr) - len(row))
        d = dict(zip(hdr, row))
        num = id_num(d.get(fmap["id"], ""))
        if num is None:
            continue
        k = norm_kind(d.get(fmap["type"], ""))
        if k == "void":
            recs.append(Rec(num, k))
            continue
        try:
            status = norm_status(d[fmap["status"]])
            status = HARBOR_STATUS.get(status, status)
            wname = fmap["weight"]
            col_unit = None
            m = re.search(r"_(kg|g|lb|oz)$", wname)
            if m:
                col_unit = m.group(1)
            hint = col_unit or row_unit or unit or "kg"
            kg = weight_kg(d[wname], hint, comma_dec)
            month = month_of_date(parse_date(d[fmap["date"]], date_form))
        except Exception as e:
            warn("bad row", depot, row, e)
            continue
        recs.append(Rec(num, k, month, kg, status))
    return seq, recs


# ---------- fixed width ----------
FW = {  # name: (length, fields)
    "FW1": (42, dict(id=(0, 9), type=(9, 10), date=(10, 17), weight=(17, 25), status=(25, 26)),
            "yyyyddd", "g", Decimal(1)),
    "FW2": (43, dict(type=(0, 1), id=(1, 10), date=(10, 18), weight=(18, 26), status=(26, 27)),
            "yyyymmdd", "kg", Decimal("0.01")),
    "FW3": (41, dict(id=(0, 9), date=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)),
            "yyyyddd", "lb", Decimal("0.1")),
}


def parse_fixed(text):
    seq = None
    layout = None
    recs = []
    by_len = {v[0]: k for k, v in FW.items()}
    for l in lines_of(text):
        if l.startswith("\x0c"):
            l = l[1:]
            if "LISTING" in l.upper() or "PAGE" in l.upper():
                continue
        if not l.strip():
            continue
        if l.startswith("#"):
            m = re.match(r"#\s*LAYOUT\s+(\w+)", l, re.I)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"#\s*SEQ\s+(\d+)", l, re.I)
            if m:
                seq = int(m.group(1))
            continue
        name = by_len.get(len(l))
        if name is None:
            if layout in FW and len(l) < FW[layout][0]:
                l = l.ljust(FW[layout][0])
                name = layout
            else:
                warn("unrecognised south line", repr(l))
                continue
        _, f, dform, unit, scale = FW[name]
        g = {k: l[a:b] for k, (a, b) in f.items()}
        num = id_num(g["id"])
        if num is None:
            continue
        k = norm_kind(g["type"])
        if k == "void":
            recs.append(Rec(num, k))
            continue
        try:
            kg = Decimal(int(g["weight"])) * scale * KG[unit]
            month = month_of_date(parse_date(g["date"], dform))
            status = FW_STATUS[g["status"].strip().upper()]
        except Exception as e:
            warn("bad fixed row", repr(l), e)
            continue
        recs.append(Rec(num, k, month, kg, status))
    return seq, recs


# ---------- JSON lines ----------
def parse_json(text):
    seq = None
    recs = []
    for l in lines_of(text):
        if not l.strip():
            continue
        try:
            v = json.loads(l, parse_float=Decimal, parse_int=Decimal)
        except ValueError:
            warn("bad json line", l[:80])
            continue
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and "id" not in o:
                if isinstance(o["meta"], dict) and "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            num = id_num(str(o.get("id", "")))
            if num is None:
                continue
            k = norm_kind(o.get("kind", ""))
            if k == "void":
                recs.append(Rec(num, k))
                continue
            try:
                wk = [x for x in o if x.lower().startswith("weight")][0]
                m = re.search(r"_(kg|g|lb|oz)$", wk.lower())
                kg = weight_kg(str(o[wk]), m.group(1) if m else "kg", False)
                month = month_of_time(o["shipped_at"])
                status = norm_status(o["status"])
            except Exception as e:
                warn("bad json record", o, e)
                continue
            recs.append(Rec(num, k, month, kg, status))
    return seq, recs


# ---------- XML ----------
def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = parse_unit(root.get("weight-unit")) or "kg"
    recs = []
    for el in root.iter("shipment"):
        def get(name):
            if el.get(name) is not None:
                return el.get(name)
            c = el.find(name)
            return c.text if c is not None and c.text is not None else None
        num = id_num(el.get("id") or get("id"))
        if num is None:
            continue
        k = norm_kind(el.get("type") or "")
        if k == "void":
            recs.append(Rec(num, k))
            continue
        try:
            w = el.find("weight")
            if w is not None:
                unit = parse_unit(w.get("unit")) or root_unit
                kg = weight_kg(w.text, unit, False)
            else:
                kg = weight_kg(el.get("weight"), root_unit, False)
            s = get("shipped")
            if re.match(r"\d{4}-\d\d-\d\d[T ]", s.strip()):
                month = month_of_time(s)
            else:
                month = month_of_date(parse_date(s, "iso"))
            status = norm_status(get("status"))
        except Exception as e:
            warn("bad xml record", num, e)
            continue
        recs.append(Rec(num, k, month, kg, status))
    return seq, recs


# ---------- main ----------
def read_export(depot, path):
    b = read_bytes(path)
    if depot == "central":
        return parse_xml(b)
    text = decode(b)
    if depot == "south":
        return parse_fixed(text)
    if depot == "north":
        return parse_json(text)
    if depot in DELIM:
        return parse_delimited(depot, text)
    warn("unknown depot", depot)
    return None, []


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.setdefault(name.split("-", 1)[0].lower(), []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for p in paths:
            seq, recs = read_export(depot, p)
            exports.append((seq if seq is not None else -1, os.path.basename(p), recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: PRIORITY.index(d) if d in PRIORITY else len(PRIORITY)
    owners = {}
    for depot in sorted(current, key=rank):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for o in owners.values() if len(o) > 1)
    depots = {d: [0, Decimal(0)] for d in sorted(files)}
    months = {}
    for num, o in owners.items():
        r = current[o[0]][num]
        if r.status not in ("delivered", "delivered_late"):
            continue
        depots[o[0]][0] += 1
        depots[o[0]][1] += r.kg
        m = months.setdefault(r.month, [0, Decimal(0)])
        m[0] += 1
        m[1] += r.kg
    q = lambda x: float(x.quantize(Decimal("0.01"), ROUND_HALF_UP))
    out = {
        "depots": {d: {"shipments": v[0], "total_kg": q(v[1])} for d, v in depots.items()},
        "months": {m: {"shipments": v[0], "total_kg": q(v[1])} for m, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
E
cd /app && time python3 bin/summarize.py data out/summary.json 2>&1 | sort | uniq -c | head -20; python3 tools/check_summary.py; head -c 600 out/summary.json

