import sys,os,collections
sys.path.insert(0,'bin')
import summarize as s
D='data'
files=collections.defaultdict(list)
for n in sorted(os.listdir(D)): files[n.split('-')[0]].append(D+'/'+n)
for dep,ps in files.items():
    ex=[]
    for p in ps:
        seq,recs=s.read_export(dep,p); ex.append((seq,p,recs))
    ex.sort(key=lambda e:e[0])
    seqs=[e[0] for e in ex]
    cur=set(); miss=0; dupseq=len(seqs)-len(set(seqs))
    for _,_,recs in ex:
        for r in recs:
            if r.kind=='new': cur.add(r.num)
            elif r.num not in cur: miss+=1
            if r.kind=='void': cur.discard(r.num)
    print(dep,len(ex),'dupseq',dupseq,'orphans',miss,[os.path.basename(e[1]) for e in ex][:20] if dep=='central' else '')
